toolArgs.file_text:
@* Main message area: header, scrollable messages, input *@
@inject IChatService ChatService
@inject IJSRuntime JS

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p>@ChannelDescription</p>
    </div>

    <div class="message-list" @ref="messageListRef" @onscroll="HandleScroll">
        @if (isLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }

        @foreach (var message in Messages)
        {
            <MessageBubble Message="message"
                           ThreadReplyCount="GetThreadReplyCount(message.Id)"
                           OnOpenThread="OnOpenThread"
                           OnReact="(emoji) => HandleReaction(message.Id, emoji)" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSend="HandleSend" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public EventCallback<Message> OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReaction { get; set; }

    private ElementReference messageListRef;
    private bool isLoadingMore;

    private int GetThreadReplyCount(int messageId)
    {
        var summary = ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);
        return summary?.ReplyCount ?? 0;
    }

    private async Task HandleSend(string content)
    {
        await OnSendMessage.InvokeAsync(content);
        await ScrollToBottom();
    }

    private async Task HandleReaction(int messageId, string emoji)
    {
        await OnReaction.InvokeAsync((messageId, emoji));
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50 && !isLoadingMore)
        {
            isLoadingMore = true;
            await OnLoadMore.InvokeAsync();
            isLoadingMore = false;
        }
    }

    private async Task ScrollToBottom()
    {
        await Task.Delay(50);
        await JS.InvokeVoidAsync("eval", "document.querySelector('.message-list')?.scrollTo(0, document.querySelector('.message-list').scrollHeight)");
    }
}

